#!/usr/bin/env python3
from itertools import permutations

def check_flag_format(perm):
    # First ensure required prefix 'flag{'
    if ''.join(perm[:5]) != 'flag{':
        return False

    # Ensure last character is '}'
    if perm[-1] != '}':
        return False

    return True

def looks_like_word(s):
    # Some common substrings we might expect
    common_words = ['unwrang', 'wrang', 'flag', 'me']
    # Common leetspeak replacements
    leetspeak = {'3': 'e', '4': 'a'}

    # Convert leetspeak numbers back to letters for checking
    test_str = s
    for num, letter in leetspeak.items():
        test_str = test_str.replace(num, letter)

    # Check if any common words appear
    for word in common_words:
        if word in test_str.lower():
            return True

    return False

def unwrangle():
    scrambled = "aul_3fnd}{m4_lur3wgng"
    chars = list(scrambled)

    # We know 'flag{' must be the first 5 chars and '}' the last char
    # So we need to arrange: ul_3fnd}{m4_lur3wgng
    # First, remove the known positions
    remaining = [c for c in chars if c not in 'flag{}']

    # Try all permutations of remaining characters
    for perm in permutations(remaining):
        # Build candidate by inserting known positions
        candidate = ['f','l','a','g','{'] + list(perm) + ['}']

        # Check if it matches our criteria
        if check_flag_format(candidate):
            flag = ''.join(candidate)
            # Only print if it looks promising
            if looks_like_word(flag[5:-1]):  # Check the middle part
                print(f"Possible flag: {flag}")

if __name__ == "__main__":
    unwrangle()

