def get_scrambled_flag():
    # Try with different timeout values
    try:
        conn = remote('rev.chal.csaw.io', 8000, timeout=5)
        # Send a newline in case input is expected
        conn.sendline(b'')
        # Try to receive more data
        flag = b''
        while True:
            try:
                data = conn.recv(timeout=1)
                if not data:
                    break
                flag += data
            except:
                break
        conn.close()
        return flag.strip().decode('utf-8', errors='ignore')
    except Exception as e:
        print(f"Error: {e}")
        return None

# Collect multiple samples with more verbose output
