from pwn import *
import time

def get_scrambled_flag():
    try:
        conn = remote('rev.chal.csaw.io', 8000)
        response = conn.recvall().decode().strip()
        conn.close()
        if 'win' in response:
            return response.split('\n')[1]  # Get the second line
        return response
    except:
        return None

# Collect samples
samples = set()
for _ in range(5):
    flag = get_scrambled_flag()
    if flag:
        samples.add(flag)
    time.sleep(1)

print("Collected Scrambled Flags:")
for sample in samples:
    print(sample)

# Analyze patterns
def analyze_scrambled_flags(samples):
    print("\nAnalysis:")

    # Length check
    lengths = {len(s) for s in samples}
    print(f"Flag lengths: {lengths}")

    # Character set analysis
    all_chars = set(''.join(samples))
    print(f"\nUnique characters used: {''.join(sorted(all_chars))}")

    # Frequency analysis
    char_freq = {}
    for sample in samples:
        for c in sample:
            char_freq[c] = char_freq.get(c, 0) + 1
    print("\nCharacter frequencies:")
    for c, freq in sorted(char_freq.items()):
        print(f"{repr(c)}: {freq}")

    # Look for consistent positions
    if len(samples) > 0:
        length = len(next(iter(samples)))
        consistent_pos = {}
        for pos in range(length):
            chars_at_pos = {s[pos] for s in samples}
            if len(chars_at_pos) == 1:
                consistent_pos[pos] = next(iter(chars_at_pos))
        print("\nConsistent positions:")
        print(consistent_pos)

    # Count total number of each significant character
    special_chars = {'3': 0, '4': 0, '_': 0, '{': 0, '}': 0}
    for sample in samples:
        for c in special_chars:
            special_chars[c] += sample.count(c)
    print("\nSpecial character counts (avg per flag):")
    for c, count in special_chars.items():
        if len(samples) > 0:
