#!/usr/bin/env python3
from pwn import *
import sys

def collect_samples(count=10):
    samples = []
    for i in range(count):
        conn = remote('rev.chal.csaw.io', 8000)
        response = conn.recvline().strip().decode()
        samples.append(response)
        conn.close()
    return samples

def analyze_samples(samples):
    # Print all samples
    print("Collected samples:")
    for i, s in enumerate(samples):
        print(f"{i+1}. {s}")

    # Analyze length and character positions
    lengths = set(len(s) for s in samples)
    print(f"\nAll strings have lengths: {lengths}")

    # Find constant positions
    if len(samples) > 1:
        sample_len = len(samples[0])
        constants = []
        for pos in range(sample_len):
            chars = set(s[pos] for s in samples)
            if len(chars) == 1:
                constants.append((pos, list(chars)[0]))
        print("\nConstant positions:")
        for pos, char in constants:
            print(f"Position {pos}: '{char}'")

if __name__ == "__main__":
    samples = collect_samples(5)
    analyze_samples(samples)

